@@ -1,324 +0,0 @@
-// SPDX-License-Identifier: Apache-2.0
-//
-// FlatBars adapter — backs the lab's three FlatBars dialect engines (RawBars /
-// FullBars / MaxBars), selected by the dialect argument to
-// `createFlatBarsRenderer()`. Like stem.mjs and minbars.mjs it returns the SAME
-// seam shape (render, compile, parseAst, inspectAt, usedTransformers,
-// requiredAssigns, partialGraph, allTransformers, catalog, engineInfo, version),
-// so the host wires it through the identical contract and the capability gate
-// hides whatever FlatBars doesn't (yet) back.
-//
-// FlatBars is a PureScript engine compiled to JS — no WASM. The engine is the
-// `flatbars-js` facade, bundled to `vendor/flatbars-engine.mjs` (regenerate with
-//   spago bundle -p flatbars-js --module FullBars.JS \
-//     --bundle-type module --platform browser --outfile vendor/flatbars-engine.mjs
-// ). It renders the **surface** dialect by default — the Handlebars-compatible
-// layer (paths, `{{ }}` auto-escape, `@data`, `else`/`elif`) — which is the
-// right basis for cross-engine comparison; the austere **core** dialect is an
-// option (the FlatBars-specific control, surfaced in Phase 2).
-//
-// Supported: render (core + surface dialects, `?dialect=`), the lowered AST
-// (parseAst), data-access (required-assigns), the helper catalog, and the
-// partial graph (multi-document partials). The generic rt.block fallback for
-// exotic block helpers and `inspectAt` are not yet implemented, so those
-// features are not advertised and the matching panels gate off.
-
-import {
-  render as bbRender,
-  renderSurface as bbRenderSurface,
-  renderSurfaceWithPartials as bbRenderSurfaceWith,
-  renderMaxbars as bbRenderMaxbars,
-  renderMaxbarsWithPartials as bbRenderMaxbarsWith,
-  astJson,
-  compile as bbCompile,
-  compileSurface as bbCompileSurface,
-  compileMaxbars as bbCompileMaxbars,
-  compileMaxbarsWithPartials as bbCompileMaxbarsWith,
-  renderWith as bbRenderWith,
-  renderRawWith as bbRenderRawWith,
-  renderMaxWith as bbRenderMaxWith,
-  renderSurfaceI18n as bbRenderSurfaceI18n,
-  analyze as bbAnalyze,
-  analyzeWith as bbAnalyzeWith,
-  lint as bbLint,
-  migrate as bbMigrate,
-} from "./vendor/flatbars-engine.mjs?v=70";
-
-const BB_VERSION = "0.1.0";
-
-// Map a UI/param dialect name to the engine's internal dialect, or `null` for an
-// unrecognised value. `rawbars`→"core", `fullbars`→"surface", `maxbars` is its
-// own engine entrypoint (FullBars + infix operators, pipes, bare loop variables).
-function normalizeDialect(d) {
-  if (d === "maxbars" || d === "core" || d === "surface") return d;
-  if (d === "rawbars") return "core";
-  if (d === "fullbars") return "surface";
-  return null;
-}
-
-// The active dialect, from `?dialect=` (the header dialect toggle sets this
-// param); defaults to the Handlebars-flavoured surface.
-const DIALECT = (() => {
-  if (typeof location === "undefined") return "surface";
-  return normalizeDialect(new URLSearchParams(location.search).get("dialect")) ?? "surface";
-})();
-
-// engine-features/v1 capability vector. FlatBars backs rendering, a static helper
-// catalog (→ Transformers panel), exact data-access (→ Data Access panel — the
-// surface dialect desugars every bare path to `lookup`), and a partial graph
-// (→ Partials panel; {{> name}}/{{#inline}} surface as partial nodes). AST-only
-// Stem features (standalone-whitespace, provenance, …) stay absent, gated off.
-const BB_FEATURES = [
-  "catalog",
-  "required-assigns",
-  "partial-graph",
-  "compile-js", // FlatBars-only: compile the template to a JS module (Compiled JS view)
-  "analyse", // ADR-022: trace a render, report truthiness portability (Truthiness view)
-  "lint", // ADR-019: deprecated-alias + non-canonical scoped-variable warnings (Lint panel)
-  "migrate", // Handlebars → MaxBars source rewrite, with a residual report (Migrated view)
-  "surface-dialect", // {{ }} auto-escape, paths, @data, else/elif (Handlebars-flavoured)
-  "core-dialect", // the austere meaning-free core syntax
-  "maxbars-dialect", // FullBars + infix operators, pipes, bare loop variables
-];
-
-// The prelude helpers, with the metadata the cheat-sheet panel renders (mirrors
-// Stem.Transformers.Catalog.entries / HB_CATALOG). Generated single source is
-// `docs/.../helper-catalog.adoc`; this is the user-facing subset.
-const BB_CATALOG = [
-  { name: "if", category: "logic", arity: "block", summary: "Render the block when the argument is truthy; supports {{elif}} / {{else}} clauses.", example: "{{#if active}}on{{elif other}}alt{{else}}off{{/if}}" },
-  { name: "unless", category: "logic", arity: "block", summary: "The inverse of if.", example: "{{#unless done}}todo{{/unless}}" },
-  { name: "each", category: "collections", arity: "block", summary: "Iterate an array or object; @index/@key/@first/@last (and @../index) in scope. MaxBars adds bare loop vars: index0/index1/rindex0/rindex1/length (aliases index/rindex/size).", example: "{{#each items}}{{ this }}{{/each}}" },
-  { name: "with", category: "access", arity: "block", summary: "Shift context into the argument for the block.", example: "{{#with user}}{{ name }}{{/with}}" },
-  { name: "lookup", category: "access", arity: "inline", summary: "Variadic path lookup; the target of surface path desugaring.", example: "{{{ lookup this \"a\" \"b\" }}}" },
-  { name: "eq", category: "logic", arity: "inline", summary: "Value equality ⇒ boolean. Also ne/lt/gt/lte/gte, and/or/not.", example: "{{#if (eq a b)}}…{{/if}}" },
-  { name: "escapeHtml", category: "output", arity: "inline", summary: "HTML-escape a value (idempotent on safe values).", example: "{{{ escapeHtml x }}}" },
-  { name: "safe", category: "output", arity: "inline", summary: "Mark a value as trusted markup (no escaping).", example: "{{{ safe html }}}" },
-  { name: "json", category: "output", arity: "inline", summary: "Serialize a value as JSON text; pretty=true indents.", example: "{{{ json this pretty=true }}}" },
-  { name: "escapeJson", category: "output", arity: "inline", summary: "JSON + HTML-escape (for embedding in HTML).", example: "{{{ escapeJson this }}}" },
-  { name: "dict", category: "data", arity: "inline", summary: "Build an object from key/value pairs (target of hash args).", example: "{{#if n (dict \"includeZero\" true)}}…{{/if}}" },
-  { name: "partial", category: "composition", arity: "inline", summary: "Render a registered partial; block form gives a fallback + {{> @partial-block}}.", example: "{{> nav user}}" },
-];
-
-export async function createFlatBarsRenderer(dialectArg) {
-  // No async init — the engine is synchronous JS. The async signature mirrors the
-  // Stem adapter so the host's `await create…()` site stays uniform.
-  //
-  // The active dialect is fixed by the engine choice: the lab now exposes the
-  // three FlatBars dialects as first-class engines (RawBars→"core",
-  // FullBars→"surface", MaxBars→"maxbars"), so the host passes the dialect in.
-  // Falls back to the `?dialect=` URL default for back-compat / per-call use.
-  const activeDialect = normalizeDialect(dialectArg) ?? DIALECT;
-
-  // Map the engine's `{ ok, value, error }` result to the seam's render contract:
-  // the string on success, a thrown `{ kind: "render" }` error otherwise.
-  function renderResult(res, map) {
-    if (res.ok) return map ? { output: res.value, segments: [] } : res.value;
-    const err = new Error(res.error);
-    err.kind = "render";
-    throw err;
-  }
-
-  // `program` is opaque to the host: it carries the source, the active dialect,
-  // and the named partial documents (the host's multi-document sources).
-  function compile(source, partials = {}, opts = {}) {
-    // No separate compile step — render reports located parse errors directly.
-    // An explicit `opts.dialect` overrides the URL-driven default (used by tests
-    // and any host that selects per-call); `rawbars`/`fullbars` are the engine's
-    // "core"/"surface". `opts.helpers` is a built `{ name: fn }` bag of
-    // user-defined helpers (ADR-018) — surface/FullBars only.
-    const dialect = normalizeDialect(opts.dialect) ?? activeDialect;
-    return { program: { source, dialect, partials: partials || {}, helpers: opts.helpers || null, translator: opts.translator || null } };
-  }
-
-  function render(program, data, { map = false, policy } = {}) {
-    if (policy != null) {
-      const err = new Error("FlatBars has no render-time { allow, eval } policy");
-      err.kind = "unsupported-policy";
-      throw err;
-    }
-    const d = data == null ? {} : data;
-    const hasPartials = program.partials && Object.keys(program.partials).length > 0;
-    const hasHelpers = program.helpers && Object.keys(program.helpers).length > 0;
-    let res;
-    if (program.translator) {
-      // ADR-029: localization wires the first-class translator seam (not
-      // registerHelper) — the surface render with `t`/`number`/`date`/… driven by
-      // the host translator. (The Lab's i18n examples are FullBars/surface.)
-      res = bbRenderSurfaceI18n(program.translator, program.source, d);
-    } else if (program.dialect === "core") {
-      // Custom operations (ADR-019 addendum) register through RawBars' strict
-      // registrar (which also threads external partials); with partials but no
-      // operations, the same registrar with an empty op set; else the plain render.
-      res = hasHelpers
-        ? bbRenderRawWith(program.helpers, program.partials || {}, program.source, d)
-        : hasPartials
-          ? bbRenderRawWith({}, program.partials, program.source, d)
-          : bbRender(program.source, d);
-    } else if (program.dialect === "maxbars") {
-      // MaxBars reuses the FullBars surface pipeline. External (host-threaded)
-      // partials now thread through its entrypoints: the operation registrar when
-      // custom ops are present (a raw block's `{{{{#op}}}}` also resolves there),
-      // renderMaxbarsWithPartials for partials alone, else the plain render.
-      res = hasHelpers
-        ? bbRenderMaxWith(program.helpers, program.partials || {}, program.source, d)
-        : hasPartials
-          ? bbRenderMaxbarsWith(program.partials, program.source, d)
-          : bbRenderMaxbars(program.source, d);
-    } else if (hasHelpers) {
-      // Custom helpers (ADR-018) render through the facade's renderWith, which
-      // also threads partials — the surface/FullBars path.
-      res = bbRenderWith(program.helpers, program.partials || {}, program.source, d);
-    } else {
-      res = hasPartials
-        ? bbRenderSurfaceWith(program.partials, program.source, d)
-        : bbRenderSurface(program.source, d);
-    }
-    return renderResult(res, map);
-  }
-
-  // Analyse mode (ADR-022 Part B): render + report the truthiness decisions that
-  // would branch differently on another engine. Returns the facade's
-  // { ok, report, jsonata, output, error } object (always the FullBars rule).
-  function analyze(program, data) {
-    const d = data == null ? {} : data;
-    return bbAnalyze(program.source, d);
-  }
-
-  // ADR-030: `analyze` with a host path schema — `schema(path, value) => boolean`
-  // ("could this path hold this value?") suppresses potential what-ifs the host's
-  // types rule out. Same result shape as `analyze`.
-  function analyzeWith(schema, program, data) {
-    const d = data == null ? {} : data;
-    return bbAnalyzeWith(schema, program.source, d);
-  }
-
-  // Canonicalization lint (ADR-019, the `lint` feature): the deprecated-alias and
-  // non-canonical scoped-variable warnings for the active dialect. Returns the
-  // facade's { ok, findings: [{severity, name, message}], report, error } object.
-  // The scoped-variable lint is surface-scoped, so it runs for rawbars/maxbars but
-  // not the FullBars surface — exactly as `flatbars lint` does on the CLI. The
-  // facade keys on the UI dialect name, so map the engine-internal one back
-  // (`core` → `rawbars`, `surface` → `fullbars`).
-  function lint(source, dialect) {
-    const internal = normalizeDialect(dialect) ?? activeDialect;
-    const ui = internal === "core" ? "rawbars" : internal === "surface" ? "fullbars" : internal;
-    return bbLint(source, ui);
-  }
-
-  // Handlebars → MaxBars source migration (the `migrate` feature): returns the
-  // facade's { ok, source, residuals: [{kind, message, suggestion}], error }
-  // object. Drives the "Migrated MaxBars" output view; residuals are the shapes
-  // the migrator flagged for a human rather than guessing.
-  function migrate(source) {
-    return bbMigrate(source);
-  }
-
-  // ── AST + static analyses ──────────────────────────────────────────────────
-  // parseAst returns the lowered AST in the host's {t:…} node shape (or {error}).
-  // The engine facade does the parse+lower+map in PureScript; the analyses below
-  // walk that shape, exactly like the Handlebars adapter walks its mapped nodes.
-
-  function parseAst(source, opts = {}) {
-    return astJson(normalizeDialect(opts.dialect) ?? activeDialect, source);
-  }
-
-  // FlatBars-specific (the `compile-js` feature): compile the template to a JS
-  // ES module via FlatBars.Compile, honouring the active dialect. `partials` is an
-  // optional `{ name: source }` bag of external partials folded into the compiled
-  // module's registry (MaxBars; the compiled twin of renderMaxbarsWithPartials).
-  // Returns `{ ok, value, error }` — `value` is the JS source. Drives the Compiled
-  // JS view. (The signature mirrors the MinBars adapter's compileToJs(src, partials).)
-  function compileToJs(source, partials) {
-    const ps = partials && Object.keys(partials).length > 0 ? partials : null;
-    if (activeDialect === "maxbars") return ps ? bbCompileMaxbarsWith(ps, source) : bbCompileMaxbars(source);
-    if (activeDialect === "core") return bbCompile(source);
-    return bbCompileSurface(source);
-  }
-
-  function walk(nodes, visit) {
-    for (const node of nodes || []) {
-      visit(node);
-      for (const key of ["then", "else", "body"]) {
-        if (Array.isArray(node[key])) walk(node[key], visit);
-      }
-    }
-  }
-  function walkExpr(expr, visit) {
-    if (!expr || typeof expr !== "object") return;
-    visit(expr);
-    if (expr.t === "call") for (const a of expr.args || []) walkExpr(a.value, visit);
-  }
-
-  // Every expression position in a node (the emitted value, a condition/subject,
-  // and any call arguments).
-  function eachExpr(node, fn) {
-    if (node.t === "emit") fn(node.expr);
-    if (node.cond) fn(node.cond);
-    if (node.subject) fn(node.subject);
-    if (Array.isArray(node.args)) for (const a of node.args) fn(a.value);
-  }
-
-  function nodesOf(program) {
-    const parsed = astJson(program.dialect, program.source);
-    return parsed.ast ? parsed.ast.nodes : [];
-  }
-
-  // required-assigns (EXACT for FlatBars): the root of every `{t:"path"}` — i.e.
-  // every bare/dotted data path. Helpers are explicit calls and block params are
-  // `(param)` calls, so neither leaks in (unlike the Handlebars approximation).
-  function requiredAssigns(program) {
-    const out = new Set();
-    walk(nodesOf(program), (node) =>
-      eachExpr(node, (e) => walkExpr(e, (x) => {
-        if (x.t === "path" && x.segments && x.segments.length) out.add(x.segments[0]);
-      })),
-    );
-    return [...out].sort();
-  }
-
-  // used-transformers: block-helper node types (if/unless/each/with + any custom
-  // block) and every `{t:"call"}` head.
-  function usedTransformers(program) {
-    const names = new Set();
-    const STRUCTURAL = new Set(["text", "emit", "sep", "raw"]);
-    walk(nodesOf(program), (node) => {
-      if (["if", "unless", "each", "with"].includes(node.t)) names.add(node.t);
-      else if (node.t && !STRUCTURAL.has(node.t)) names.add(node.t); // custom block helper
-      eachExpr(node, (e) => walkExpr(e, (x) => { if (x.t === "call" && x.name) names.add(x.name); }));
-    });
-    return [...names].sort();
-  }
-
-  function inspectAt() {
-    const err = new Error("FlatBars context inspector is not implemented yet");
-    err.kind = "unsupported";
-    throw err;
-  }
-  // partial-graph is not advertised yet (FlatBars partials are `partial` calls,
-  // not distinct AST nodes — a Phase-3 mapping), so the Partials panel gates off.
-  function partialGraph() { return { nodes: [], edges: [], cycles: [] }; }
-  function allTransformers() { return BB_CATALOG.map((e) => e.name); }
-  function catalog() { return BB_CATALOG; }
-  function engineInfo() {
-    return { version: BB_VERSION, builtins: allTransformers(), features: BB_FEATURES };
-  }
-
-  return {
-    render,
-    analyze,
-    analyzeWith,
-    lint,
-    migrate,
-    compile,
-    parseAst,
-    inspectAt,
-    usedTransformers,
-    requiredAssigns,
-    partialGraph,
-    allTransformers,
-    catalog,
-    compileToJs,
-    engineInfo,
-    version: BB_VERSION,
-  };
-}

@@ -1636,8 +1636,7 @@
       // Cache-bust query (like playground_utils.mjs): bump on any change to the
       // engine adapters so a reload never pairs a fresh index.html / example
       // file with a stale cached adapter module.
-      import { createFlatBarsRenderer } from "./flatbars.mjs?v=6";
-      import { createMinBarsRenderer } from "./minbars.mjs?v=2";
+      import { createRenderer } from "./renderer.mjs?v=1";
       // Engine-derived INNER-TOKEN highlighting (ADR-014 amendment): the shared
       // painter + the lexer's own tokenizer, in place of a hand-written tag regex.
       import { flatbarsHighlight } from "./cm-flatbars.mjs?v=6";
@@ -1753,13 +1752,9 @@
                : DIALECT_PARAM === "maxbars" ? "maxbars" : "fullbars")
         // Default to FullBars — the Handlebars-like FlatBars surface.
         : "fullbars";
-      // The three FlatBars dialect engines share one adapter; the engine name
-      // fixes the dialect it renders.
-      const BB_DIALECT = { rawbars: "core", fullbars: "surface", maxbars: "maxbars" };
-
-      const renderer =
-        BB_DIALECT[ENGINE] ? await createFlatBarsRenderer(BB_DIALECT[ENGINE])
-        : await createMinBarsRenderer();
+      // One adapter backs every engine; createRenderer maps the engine name to its
+      // dialect (rawbars→core, fullbars→surface, maxbars, minbars).
+      const renderer = await createRenderer(ENGINE);
       // Show the engine + its version (from the bundled FlatBars/MinBars engine).
       const ENGINE_LABEL =
         ENGINE === "rawbars" ? "RawBars"

@@ -1,137 +0,0 @@
-// SPDX-License-Identifier: Apache-2.0
-//
-// MinBars adapter — the engine-neutral playground's Mustache engine.
-// `createMinBarsRenderer()` returns the same object shape as the other engine
-// adapters (render, compile, compileToJs, parseAst, inspectAt, usedTransformers,
-// requiredAssigns, partialGraph, allTransformers, catalog, engineInfo,
-// version), so the host wires it through the identical seam.
-//
-// MinBars is a *peer engine* to FullBars (Mustache semantics — a context stack
-// with parent fallback, polymorphic sections, `false null []` truthiness),
-// rendering the in-scope mustache/spec suite. It now also compiles to JS
-// (`compileToJs`, ADR-016), so the Compiled JS view lights up; it still has no
-// helper registry or lowered-AST seam, so the catalog stays small and the
-// AST-analysis panels (Context Inspector, partial graph) gate off.
-
-import {
-  renderMustache as bbRenderMustache,
-  renderMinbarsCompat as bbRenderMinbarsCompat,
-  renderMinbarsCompatWithPartials as bbRenderMinbarsCompatWith,
-  compileMinbars as bbCompileMinbars,
-  compileMinbarsWithPartials as bbCompileMinbarsWithPartials,
-  compileMinbarsCompat as bbCompileMinbarsCompat,
-  compileMinbarsCompatWithPartials as bbCompileMinbarsCompatWith,
-} from "./vendor/flatbars-engine.mjs?v=70";
-
-const MIN_VERSION = "0.1.0";
-
-// engine-features/v1 capability vector for MinBars. It renders + has (Mustache)
-// partials + a catalog + a JS compiler (ADR-016). Compared with the FlatBars
-// adapter's set, the AST-analysis features (lowered-AST seam, required-assigns,
-// partial-graph) are absent — there is no lowered AST here.
-const MIN_FEATURES = ["partials", "catalog", "compile-js"];
-
-// The Mustache constructs, with the metadata the Transformers/cheat-sheet panel
-// renders (mirrors the shape of the other adapters' catalogs). Mustache has no
-// helpers; these are the tag *forms* the engine implements.
-const MIN_CATALOG = [
-  { name: "{{name}}", category: "interpolation", arity: "inline", summary: "Interpolate a name (HTML-escaped); {{{name}}} / {{&name}} are raw. Resolves up the context stack with parent fallback; {{.}} is the implicit iterator.", example: "Hello {{name}}!" },
-  { name: "#section", category: "sections", arity: "block", summary: "Polymorphic section: render once per array element (pushed), once for a truthy non-list, or never for a falsy value (false/null/[]).", example: "{{#items}}{{.}}{{/items}}" },
-  { name: "^inverted", category: "sections", arity: "block", summary: "Render the block only when the value is falsy (false/null/empty list).", example: "{{^items}}none{{/items}}" },
-  { name: ">partial", category: "composition", arity: "inline", summary: "Include a partial, rendered against the current context stack and re-indented when standalone. {{>* name}} resolves the partial name from context.", example: "{{> item}}" },
-  { name: "<parent", category: "inheritance", arity: "block", summary: "Expand a parent template, overriding its {{$blocks}}. {{<*name}} resolves the parent name from context.", example: "{{<base}}{{$title}}Home{{/title}}{{/base}}" },
-  { name: "$block", category: "inheritance", arity: "block", summary: "An overridable region: renders its default unless an enclosing parent overrides it.", example: "{{$title}}default{{/title}}" },
-  { name: "!comment", category: "meta", arity: "inline", summary: "A comment — dropped from output. Standalone comment lines are stripped.", example: "{{! ignored }}" },
-];
-
-export async function createMinBarsRenderer() {
-  // No async init — MinBars is synchronous JS (the compiled PureScript facade).
-  // The async signature mirrors the other adapters so the host's `await
-  // create…()` call site stays engine-agnostic.
-
-  // `program` is opaque to the host: it carries the source and the partial
-  // sources. MinBars has no separate compile step — render reports located
-  // parse errors directly — so this just packages them.
-  function compile(source, partials = {}, _opts = {}) {
-    return { program: { source, partials: partials || {} } };
-  }
-
-  // `compat` (the Lab's MinBars truthiness toggle) selects the `mustache.js`
-  // rule (`0`/`""` falsy) instead of MinBars' language-agnostic spec default
-  // (`0`/`""` truthy) — ADR-022 S2. Both rules ship in the engine bundle.
-  function render(program, data, { map = false, policy, compat = false } = {}) {
-    if (policy != null) {
-      const err = new Error("MinBars has no render-time { allow, eval } policy (Mustache is logic-less)");
-      err.kind = "unsupported-policy";
-      throw err;
-    }
-    const partials = program.partials || {};
-    const d = data == null ? null : data;
-    const hasPartials = Object.keys(partials).length > 0;
-    const res = compat
-      ? (hasPartials ? bbRenderMinbarsCompatWith(partials, program.source, d) : bbRenderMinbarsCompat(program.source, d))
-      : bbRenderMustache(partials, program.source, d);
-    if (res.ok) return map ? { output: res.value, segments: [] } : res.value;
-    const err = new Error(res.error);
-    err.kind = "render";
-    throw err;
-  }
-
-  // Compile the MinBars template to a JS ES module (the `compile-js` feature;
-  // ADR-016). Returns `{ ok, value, error }` — `value` is the JS source — driving
-  // the Compiled JS view. `{{> p}}` is inlined, so when partials are supplied they
-  // are compiled in; without them a partial inlines to "" (as a missing partial
-  // renders). Recursive/dynamic partials and dynamic-name parents compile-reject
-  // with a clear error (slice limitation), matching the engine.
-  function compileToJs(source, partials, { compat = false } = {}) {
-    const hasPartials = partials && Object.keys(partials).length;
-    if (compat) {
-      return hasPartials ? bbCompileMinbarsCompatWith(partials, source) : bbCompileMinbarsCompat(source);
-    }
-    return hasPartials ? bbCompileMinbarsWithPartials(partials, source) : bbCompileMinbars(source);
-  }
-
-  // MinBars exposes no lowered-AST seam to the host yet, so the AST-derived
-  // panels (outline, data-access, partial-graph) gate off via the absent
-  // features. The host may still call these analyses defensively during a
-  // render, so they return EMPTY rather than throw (honest: Mustache is
